import React from 'react';

const CuadrupleHelice = () => {
    return (
        <section>
            <h2>Cuádruple Hélice</h2>
            <p>
                La propuesta también puede analizarse desde la cuádruple hélice, ya que incorpora a la sociedad civil como actor esencial en la construcción y difusión de la memoria histórica.
            </p>
            <p>
                En este marco, organizaciones juveniles, ONG educativas, comunidades estudiantiles y ciudadanía en general no solo recibirían la información, sino que también participarían activamente compartiendo contenido, promoviendo la reflexión y generando discusión pública sobre la importancia de la democracia y la historia nacional.
            </p>
            <p>
                La inclusión de la sociedad civil fortalece el impacto de la propuesta, ya que transforma el conocimiento histórico en una herramienta de participación, conciencia social y formación ciudadana.
            </p>
        </section>
    );
};

export default CuadrupleHelice;
